import streamlit as st
import streamlit.components.v1 as components
import base64
import os

st.set_page_config(
    page_title="Status AI - Stray Kids Edition",
    page_icon="🧭",
    layout="wide",
    initial_sidebar_state="collapsed",
)

st.markdown("""
<style>
    #MainMenu {visibility: hidden;}
    footer {visibility: hidden;}
    header {visibility: hidden;}
    .block-container { padding: 0rem !important; max-width: 100% !important; }
    iframe { width: 100% !important; height: 100vh !important; border: none !important; }
</style>
""", unsafe_allow_html=True)

# Try reading from app_index.html if available, otherwise fallback to embedded Base64 HTML
HTML_CONTENT = ""
if os.path.exists("app_index.html"):
    try:
        with open("app_index.html", "r", encoding="utf-8") as f:
            HTML_CONTENT = f.read()
    except Exception:
        HTML_CONTENT = ""

if not HTML_CONTENT:
    B64_DATA = ""
    HTML_CONTENT = base64.b64decode(B64_DATA).decode("utf-8")

def main():
    components.html(HTML_CONTENT, height=850, scrolling=True)

if __name__ == "__main__":
    main()
